/* A foot key. Small typewriter caps with a real hit area, so the
   actions stop reading as another sentence of the note. */
.card-key {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.2rem var(--card-key-inset);
  border: 0;
  border-radius: 2px;
  background: transparent;
  font-family: var(--font-typewriter);
  font-size: 0.6875rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  line-height: 1.3;
  color: var(--color-ink-muted);
  cursor: pointer;
  transition:
    color 0.16s ease,
    background 0.16s ease;
}
.card-key:hover:not(:disabled),
.card-key:focus-visible {
  color: var(--color-vermilion);
