@import "tailwindcss";

/*
 * TWYNE — The Editorial Room
 * ─────────────────────────────────────────────────────────────
 * Design language: a 1955 magazine bullpen filtered through
 * Wes Anderson's "The French Dispatch."  Newsprint paper,
 * editorial vermilion, periwinkle and sage departmental
 * accents, hot-press serif headlines, manuscript-grade body.
 * ─────────────────────────────────────────────────────────────
 */

@theme {
  /* ── Paper & Ink ─────────────────────────────────────── */
  --color-paper: #f4ecd8; /* aged newsprint cream */
  --color-paper-2: #ebe1c9; /* deeper paper, sidebars */
  --color-paper-3: #ddd0b1; /* paper rule */
  --color-paper-soft: #faf3df; /* highlight paper */
  --color-ink: #1f1b16; /* near-black brown */
  --color-ink-light: #4a3f33; /* secondary ink */
  --color-ink-muted: #8a7e6c; /* tertiary, set in old gravure */
  --color-editor-bg: #fbf6e7; /* manuscript page */
  --color-editor-line: #efe6cb; /* manuscript ledger line */

  /* ── Departmental Accents (color-coded sections) ─────── */
  --color-vermilion: #c1272d; /* Penguin Classics red, masthead */
  --color-vermilion-2: #9c1a1f; /* deeper vermilion */
  --color-periwinkle: #5c6bc0; /* periwinkle, departmental */
  --color-sage: #8a9a5b; /* cabinet sage */
  --color-mustard: #d4a017; /* color rule, badges */
  --color-blush: #e8a598; /* salmon, soft accents */
  --color-cobalt: #2c4a7c; /* deep ocean, callouts */
  --color-writer-note: #7f4560; /* aubergine pencil, never a persona */

  /* legacy "brand" mapped to vermilion for compat */
  --color-brand: #c1272d;
  --color-brand-light: #d65157;
  --color-brand-dark: #9c1a1f;

  /* legacy "surface" mapped to paper for compat */
  --color-surface: #f4ecd8;
  --color-surface-2: #ebe1c9;
  --color-surface-3: #ddd0b1;

  /* ── Status colors (kept, but recalibrated for paper) ── */
  --color-accent-green: #5b7a3a;
  --color-accent-amber: #b8860b;
  --color-accent-red: #b3261e;
  --color-accent-blue: #2c4a7c;

  /* ── Cast colors (the persona portraits) ─────────────── */
  --color-persona-devil: #c1272d; /* vermilion */
  --color-persona-angel: #8a9a5b; /* sage */
  --color-persona-scholar: #5c6bc0; /* periwinkle */
  --color-persona-editor: #d4a017; /* mustard */
  --color-persona-reader: #2c4a7c; /* cobalt */

  /* ── Type stack ──────────────────────────────────────── */
  --font-display: "Libre Baskerville", "Playfair Display", Georgia, serif;
  --font-serif: "Lora", "Crimson Pro", Georgia, "Times New Roman", serif;
  --font-sans: "DM Sans", "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", "Fira Code", monospace;
  --font-typewriter: "Special Elite", "Courier New", monospace;
}

/* ── Semantic z-scale ────────────────────────────────────── */
:root {
  --z-dropdown: 30;
  --z-sticky: 20;
  --z-overlay: 40;
  --z-modal: 50;
  --z-toast: 60;
}

/* ─────────────────────────────────────────────────────────────
 * Tokens referenced across the app that had no definition — they
 * were resolving to `unset`. Aliases, so they follow the theme.
 * ───────────────────────────────────────────────────────────── */
:root {
  --color-accent: var(--color-vermilion);
  --color-rule: var(--color-paper-3);
  --color-crimson: var(--color-vermilion-2);
}

/* Narration follows the prose without disturbing its Markdown structure. */
::highlight(twyne-speech-sentence) {
  background-color: color-mix(in srgb, var(--color-mustard) 20%, transparent);
}

::highlight(twyne-speech-word) {
  color: var(--color-ink);
  background-color: color-mix(
    in srgb,
    var(--color-vermilion) 26%,
    var(--color-paper)
  );
  text-decoration: underline;
  text-decoration-color: var(--color-vermilion);
  text-decoration-thickness: 2px;
  text-underline-offset: 0.16em;
}

[data-speech-active="playing"],
[data-speech-active="paused"] {
  cursor: text;
}

[data-speech-active="loading"] {
  cursor: progress;
}

[data-speech-active].is-speech-seeking {
  cursor: ew-resize;
  user-select: none;
}

/* ─────────────────────────────────────────────────────────────
 * Document colors — the text and highlight swatches in
 * `palette.ts`, which named these custom properties without any
 * of them ever being defined.
 *
 * Literal, and deliberately outside the theme blocks. These are
 * colors the writer applies to their prose; they get written into
 * the document as hex and have to render identically in an export
 * that has no stylesheet. A theme may re-ink the room, never the
 * manuscript.
 * ───────────────────────────────────────────────────────────── */
:root {
  --color-text-olive: #556134;
  --color-text-periwinkle: #454f9e;
  --color-text-amber: #7a5a07;
  --color-text-sienna: #964f40;
  --color-highlight-butter: #fbeaa8;
  --color-highlight-rose: #f8d3d4;
  --color-highlight-sky: #cfe0f2;
  --color-highlight-mint: #d5e6c4;
  --color-highlight-lilac: #dcdff4;
  --color-highlight-peach: #fadfd5;
}

/* ─────────────────────────────────────────────────────────────
 * Texture tokens
 *
 * The letterpress surfaces — paper grain, foxing, the `.folio`
 * emboss, `.ink-bleed`'s halo — used to hard-code `rgba(31,27,22,…)`
 * ink and `rgba(255,255,255,…)` highlights. Baked that way they
 * invert wrongly on any other ground: a white inset sheen on dark
 * paper reads as a scratch. Expressed against the palette instead,
 * every texture follows the active theme.
 * ───────────────────────────────────────────────────────────── */
:root {
  /* Paper tooth. Its own tokens so a preset can flatten it entirely. */
  --grain-1: color-mix(in srgb, var(--color-ink) 2.5%, transparent);
  --grain-2: color-mix(in srgb, var(--color-ink) 2%, transparent);
  --grain-3: color-mix(in srgb, var(--color-ink) 1.5%, transparent);
  /* Base colors the textures are mixed from, never used at full strength. */
  --emboss: #ffffff;
  --foxing-base: #7a5426;
  /*
   * The color shadows are cast in. On paper this is just the ink, but a
   * shadow always darkens — on a dark preset, mixing from ink would make
   * every drop shadow glow. Kept separate so presets can say so.
   */
  --shade: var(--color-ink);
}

/* ─────────────────────────────────────────────────────────────
 * Themes
 *
 * Each block redefines only the core palette; everything else is
 * expressed against it, so a preset switch is one attribute flip
 * on <html>. Writers may override the eight core tokens inline on
 * top of any preset — see `src/utils/theme.ts`.
 *
 * `system` is resolved to a concrete preset by the bootstrap
 * script before first paint, so no preset block is needed for it.
 * ───────────────────────────────────────────────────────────── */

/* Foolscap — cool grey-white, the yellow taken out. */
[data-theme="foolscap"] {
  --color-paper: #eef0f1;
  --color-paper-2: #e3e6e8;
  --color-paper-3: #c9ced2;
  --color-paper-soft: #f7f8f9;
  --color-ink: #1c2024;
  --color-ink-light: #3f464d;
  --color-ink-muted: #69727a;
  --color-editor-bg: #f9fafb;
  --color-editor-line: #e6e9eb;
  --color-vermilion: #9b4a…31570 tokens truncated…);
  font-family: var(--font-typewriter);
  font-size: 0.75rem;
  line-height: 1.3;
  text-align: left;
  cursor: pointer;
}

.site-select__option.is-active,
.site-select__option:hover {
  background: var(--color-paper-2);
  color: var(--color-ink);
}

.site-select__option.is-selected {
  color: var(--color-vermilion-2);
}

.site-select__check {
  color: var(--color-vermilion);
  font-family: var(--font-typewriter);
}

.site-select__option-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.12rem;
}

.site-select__option-copy > span {
  overflow-wrap: anywhere;
}

.site-select__option-copy small {
  color: var(--color-ink-muted);
  font-family: var(--font-serif);
  font-size: 0.6875rem;
  line-height: 1.35;
}

.mcp-connection-select {
  flex: 0 1 14rem;
  min-width: min(12rem, 100%);
}

/* A foot key. Small typewriter caps with a real hit area, so the
   actions stop reading as another sentence of the note. */
.card-key {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.2rem var(--card-key-inset);
  border: 0;
  border-radius: 2px;
  background: transparent;
  font-family: var(--font-typewriter);
  font-size: 0.6875rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  line-height: 1.3;
  color: var(--color-ink-muted);
  cursor: pointer;
  transition:
    color 0.16s ease,
    background 0.16s ease;
}
.card-key:hover:not(:disabled),
.card-key:focus-visible {
  color: var(--color-vermilion);
  background: color-mix(in srgb, var(--color-vermilion) 8%, transparent);
}
.card-key:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.card-key--go:hover:not(:disabled),
.card-key--go:focus-visible {
  color: var(--color-accent-green);
  background: color-mix(in srgb, var(--color-accent-green) 10%, transparent);
}
.card-key--on {
  color: var(--color-vermilion);
}
/* A key that destroys something. Reads quiet until you reach for it,
   then commits to vermilion — and says so before it acts. */
.card-key--danger:hover:not(:disabled),
.card-key--danger:focus-visible {
  color: var(--color-paper);
  background: var(--color-vermilion);
}
.card-key--arming {
  color: var(--color-paper);
  background: var(--color-vermilion);
}

/* Chrome that only matters once the writer is looking at this card.
   Kept in the layout at all times — only its ink fades — so nothing
   reflows on hover and the foot never changes height. Focus brings
   it back for the keyboard, and touch pointers keep it always on. */
.desk-card__reveal {
  opacity: 0;
  transition: opacity 0.18s ease;
}
.desk-card:hover .desk-card__reveal,
.desk-card:focus-within .desk-card__reveal,
.desk-card__reveal:focus-within {
  opacity: 1;
}
@media (hover: none) {
  .desk-card__reveal {
    opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .desk-card__reveal,
  .desk-card__quote,
  .card-key {
    transition: none;
  }
}

/* When a persona-coloured bubble renders Markdown on its coloured
   background, the default cobalt link and paper-3 code chip clash.
   Override against the persona color by switching the code chip to a
   translucent ink and letting links pick up the inverse highlight. */
.comment-markdown-on-color code {
  background: color-mix(in srgb, var(--color-paper) 18%, transparent);
  color: var(--color-paper);
}
.comment-markdown-on-color a {
  color: var(--color-paper);
  text-decoration-color: color-mix(
    in srgb,
    var(--color-paper) 60%,
    transparent
  );
}

/* ── The composer ─────────────────────────────────────────────────
   One surface that holds the text, the microphone and the send key,
   the way every modern chat client does it. The previous arrangement
   stacked three separate controls down the page, which read as three
   unrelated widgets rather than one place to speak from.

   The whole card takes the focus treatment, not the textarea alone —
   the writer is focusing "the composer", and a ring drawn around only
   the inner box makes the toolbar look detached from it. */
.composer {
  display: flex;
  flex-direction: column;
  background: var(--color-paper-soft);
  border: 1px solid var(--color-paper-3);
  border-radius: 3px;
  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease;
  box-shadow: 0 1px 2px color-mix(in srgb, var(--shade) 4%, transparent);
}
.composer:focus-within {
  border-color: var(--color-vermilion);
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--color-vermilion) 12%, transparent),
    0 2px 10px -6px color-mix(in srgb, var(--shade) 35%, transparent);
}
.composer[data-recording="true"] {
  border-color: var(--color-vermilion);
}
.composer[data-disabled="true"] {
  opacity: 0.6;
}

/* Borderless because the card around it already is the border. */
.composer-input {
  width: 100%;
  resize: none;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--color-ink);
  font-family: var(--font-serif);
  font-size: 0.95rem;
  line-height: 1.55;
  padding: 0.7rem 0.85rem 0.15rem;
  max-height: 40vh;
  overflow-y: auto;
}
.composer-input::placeholder {
  color: var(--color-ink-muted);
}
.composer-input:disabled {
  cursor: not-allowed;
}

.composer-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.3rem 0.5rem 0.45rem;
}
.composer-bar-left {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
  flex: 1;
}

/* The send key. Square-ish rather than a pill: this is a press, not a
   chat bubble, and a 2px radius is the house rule everywhere else. */
.composer-send {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 1.85rem;
  width: 1.85rem;
  flex-shrink: 0;
  border-radius: 2px;
  border: 1px solid var(--color-ink);
  background: var(--color-ink);
  color: var(--color-paper);
  cursor: pointer;
  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.12s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.18s ease;
}
.composer-send:hover:not(:disabled) {
  background: var(--color-vermilion-2);
  border-color: var(--color-vermilion-2);
  box-shadow: 0 4px 14px -8px
    color-mix(in srgb, var(--color-vermilion-2) 60%, transparent);
}
.composer-send:active:not(:disabled) {
  transform: translateY(1px) scale(0.97);
  box-shadow: none;
}
.composer-send:disabled {
  background: transparent;
  border-color: var(--color-paper-3);
  color: var(--color-ink-muted);
  cursor: not-allowed;
  box-shadow: none;
}

/* The keyboard hint sits next to the send key and disappears on narrow
   screens, where there is no keyboard to hint about. */
.composer-hint {
  font-family: var(--font-typewriter);
  font-size: 0.6rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-ink-muted);
  white-space: nowrap;
}
@media (max-width: 640px) {
  .composer-hint {
    display: none;
  }
}

/* Recording and transcribing both live in the toolbar rather than
   replacing the composer, so the draft the writer already typed never
   disappears behind the recorder. */
.composer-recording {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  min-width: 0;
}
.composer-rec-dot {
  height: 0.45rem;
  width: 0.45rem;
  flex-shrink: 0;
  border-radius: 9999px;
  background: var(--color-vermilion);
  animation: composer-pulse 1.2s ease-in-out infinite;
}
@keyframes composer-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.25;
  }
}
.composer-elapsed {
  font-family: var(--font-typewriter);
  font-size: 0.7rem;
  font-variant-numeric: tabular-nums;
  color: var(--color-ink);
}

@media (prefers-reduced-motion: reduce) {
  .composer-rec-dot {
    animation: none;
  }
  .composer-send:active:not(:disabled) {
    transform: none;
  }
}

/* ── The ruler ────────────────────────────────────────────────────
   Word's page ruler, in Twyne's ink. It sits directly above the page
   and spans exactly the page's width, so the markers line up with the
   real margins rather than approximating them. Dragging a marker is
   the natural way to change a margin: you move the edge of the text,
   and the text reflows under your hand.

   The shaded ends are the margins; the pale middle is the live text
   column, which is the same relationship Word draws. */
.ruler {
  position: relative;
  height: 1.35rem;
  margin: 0 auto 0.25rem;
  user-select: none;
  font-family: var(--font-typewriter);
  touch-action: none;
}
.ruler-track {
  position: absolute;
  inset: 0.3rem 0 0.3rem;
  background: var(--color-paper-3);
  border-radius: 1px;
}
.ruler-column {
  position: absolute;
  top: 0.3rem;
  bottom: 0.3rem;
  background: var(--color-paper-soft);
  border-left: 1px solid var(--color-ink-muted);
  border-right: 1px solid var(--color-ink-muted);
}
.ruler-tick {
  position: absolute;
  top: 50%;
  width: 1px;
  height: 0.3rem;
  transform: translateY(-50%);
  background: var(--color-ink-muted);
  opacity: 0.5;
}

/* Generous hit area around a deliberately small visual marker: the
   marker must not cover the text it is aligned with, but a 3px drag
   target is unusable. */
.ruler-handle {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1.1rem;
  margin-left: -0.55rem;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: ew-resize;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ruler-handle::before {
  content: "";
  width: 0;
  height: 0;
  border-left: 0.32rem solid transparent;
  border-right: 0.32rem solid transparent;
  border-top: 0.42rem solid var(--color-ink-light);
  transition:
    border-top-color 0.15s ease,
    transform 0.12s ease;
}
.ruler-handle:hover::before,
.ruler-handle:focus-visible::before {
  border-top-color: var(--color-vermilion);
  transform: scale(1.15);
}
.ruler-handle:focus-visible {
  outline: 2px solid var(--color-vermilion);
  outline-offset: 1px;
  border-radius: 2px;
}
.ruler[data-dragging="true"] .ruler-handle::before {
  border-top-color: var(--color-vermilion);
}

/* The live readout while dragging — Word shows the measurement, and
   without it the writer is guessing at what they just set. */
.ruler-readout {
  position: absolute;
  top: -1.35rem;
  transform: translateX(-50%);
  padding: 0.1rem 0.35rem;
  background: var(--color-ink);
  color: var(--color-paper);
  font-size: 0.6rem;
  letter-spacing: 0.08em;
  border-radius: 2px;
  white-space: nowrap;
  pointer-events: none;
}

.twyne-editor.zen-mode + .ruler,
.ruler[data-zen="true"] {
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}
.ruler[data-zen="true"]:hover {
  opacity: 0.6;
  pointer-events: auto;
}

@media (max-width: 640px) {
  .ruler {
    display: none;
  }
}

/* ── Lists in the manuscript ──────────────────────────────────────
   Tailwind's preflight strips markers and padding from every ul/ol,
   which left bullet and numbered lists in the editor rendering as
   bare paragraphs — the writer pressed "list" and nothing visibly
   happened. These rules restore them for the manuscript only, so the
   reset still holds for the application chrome around it.

   Markers cycle by depth the way a word processor's do, so nesting
   reads as structure rather than as an accident of indentation. */
.twyne-editor .ProseMirror ul,
.twyne-editor .ProseMirror ol {
  padding-left: 1.6em;
  margin: 0 0 1.1rem;
}
.twyne-editor .ProseMirror ul {
  list-style: disc outside;
}
.twyne-editor .ProseMirror ul ul {
  list-style-type: circle;
}
.twyne-editor .ProseMirror ul ul ul {
  list-style-type: square;
}
.twyne-editor .ProseMirror ol {
  list-style: decimal outside;
}
.twyne-editor .ProseMirror ol ol {
  list-style-type: lower-alpha;
}
.twyne-editor .ProseMirror ol ol ol {
  list-style-type: lower-roman;
}

/* Nested lists tuck under their parent rather than opening a gap. */
.twyne-editor .ProseMirror li > ul,
.twyne-editor .ProseMirror li > ol {
  margin: 0.25rem 0 0.25rem;
}
.twyne-editor .ProseMirror li {
  margin: 0.2rem 0;
  padding-left: 0.15em;
}
/* A list item's paragraph is a layout wrapper, not a new block of
   prose — the paragraph's own bottom margin would double-space the
   list. */
.twyne-editor .ProseMirror li > p {
  margin: 0;
}
.twyne-editor .ProseMirror li::marker {
  color: var(--color-ink-muted);
}
.twyne-editor .ProseMirror ol > li::marker {
  font-family: var(--font-typewriter);
  font-size: 0.85em;
}

/* The task list opts out of markers entirely; it draws checkboxes. */
.twyne-editor .ProseMirror ul[data-type="taskList"],
.twyne-editor .ProseMirror ul.twyne-task-list {
  list-style: none;
}

/* Indented blocks keep their left margin in the exported document
   too, since the indent is written as an inline style on the node. */
.twyne-editor .ProseMirror [data-indent] {
  transition: margin-left 0.12s ease;
}

/* ─────────────────────────────────────────────────────────────
 * Dossier folio — the viewport-locked filing surface
 *
 * The dossier is one sheet in a machine, not a scrolling web page:
 * the folio fills the viewport, the two columns scroll inside their
 * own frames, and advancing a step feeds a new sheet through the
 * platen rather than repainting the page.
 *
 *   .folio-shift     : the sheet-feed on every step change
 *   .folio-rail      : the department index along the bottom
 *   .carriage-input  : platen underline that travels on focus
 *   .type-caret      : blinking block caret on the live field
 *   .field-live      : the preview card currently being typed into
 * ───────────────────────────────────────────────────────────── */

@keyframes folio-feed {
  from {
    opacity: 0;
    transform: translateY(0.6rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.folio-shift {
  animation: folio-feed 0.26s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.dossier-folio-frame {
  transition:
    border-color 180ms ease,
    box-shadow 180ms ease,
    transform 180ms cubic-bezier(0.22, 1, 0.36, 1);
}

.dossier-folio-frame[data-filing-state="filing"] {
  border-color: color-mix(
    in srgb,
    var(--color-vermilion) 48%,
    var(--color-paper-3)
  );
  transform: scale(0.998);
}

.dossier-folio-frame[data-filing-state="filed"] {
  border-color: var(--color-vermilion);
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--color-vermilion) 18%, transparent),
    0 10px 24px -18px color-mix(in srgb, var(--shade) 38%, transparent);
  animation: dossier-file-settle 420ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.dossier-filed-confirmation {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  background: color-mix(in srgb, var(--color-paper) 76%, transparent);
  pointer-events: none;
  animation: dossier-filed-wash 180ms ease-out both;
}

.dossier-filed-confirmation__paper {
  display: grid;
  justify-items: center;
  min-width: min(17rem, 84vw);
  padding: 1.4rem 1.8rem 1.25rem;
  border: 2px solid var(--color-vermilion);
  background: var(--color-paper-soft);
  color: var(--color-vermilion);
  box-shadow: 0 5px 0
    color-mix(in srgb, var(--color-vermilion) 16%, transparent);
  font-family: var(--font-typewriter);
  text-align: center;
  text-transform: uppercase;
  transform: rotate(-1deg);
  animation: dossier-stamp-filed 360ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.dossier-filed-confirmation__paper strong {
  margin-top: 0.35rem;
  font-size: 1.05rem;
  letter-spacing: 0.24em;
}

.dossier-filed-confirmation__paper > span:last-child {
  margin-top: 0.45rem;
  color: var(--color-ink-light);
  font-size: 0.62rem;
  letter-spacing: 0.12em;
}

.dossier-filed-confirmation__mark {
  display: grid;
  width: 2.2rem;
  height: 2.2rem;
  place-items: center;
  border: 2px solid currentColor;
  border-radius: 50%;
  font-family: var(--font-display);
  font-size: 1.25rem;
}

@keyframes dossier-file-settle {
  from {
    transform: translateY(-0.35rem) scale(1.004);
  }
  to {
    transform: translateY(0) scale(1);
  }
}

@keyframes dossier-filed-wash {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes dossier-stamp-filed {
  from {
    opacity: 0;
    transform: translateY(-0.8rem) scale(1.16) rotate(-1deg);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1) rotate(-1deg);
    filter: blur(0);
  }
}

/* The caret that trails the live value in the dossier preview. A real
   typewriter has no cursor, but the whole point of the preview is that
   the sheet on the left is being struck as you type on the right — the
   caret is what carries that across the gutter. */
.type-caret {
  display: inline-block;
  width: 0.45em;
  height: 1em;
  margin-left: 0.1em;
  vertical-align: -0.12em;
  background: var(--color-vermilion);
  animation: type-blink 1.05s steps(1, end) infinite;
}

/* Platen rule: the baseline under a single-line answer thickens and
   colours as the carriage arrives. `background-size` animates from the
   centre out so the rule is drawn rather than swapped. */
.carriage-input {
  background-image: linear-gradient(
    to right,
    var(--color-vermilion),
    var(--color-mustard)
  );
  background-repeat: no-repeat;
  background-position: center bottom;
  background-size: 0% 2px;
  transition: background-size 0.22s cubic-bezier(0.22, 1, 0.36, 1);
}
.carriage-input:focus {
  background-size: 100% 2px;
}

.writing-format-control {
  position: relative;
}

.writing-format-control__cue {
  position: absolute;
  right: 0.4rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-vermilion);
  font-family: var(--font-typewriter);
  font-size: 0.8rem;
  pointer-events: none;
}

/* The field card on the preview that the writer is filling right now. */
.field-live {
  border-color: var(--color-vermilion);
  background: var(--color-paper);
  box-shadow: 0 0 0 1px
    color-mix(in srgb, var(--color-vermilion) 22%, transparent);
}

/* The department index that replaced the row of anonymous dots. Each
   numeral is a jump target, so it needs a hit area and a filled state. */
.folio-rail-step {
  font-family: var(--font-typewriter);
  font-size: 0.6rem;
  letter-spacing: 0.1em;
  line-height: 1;
  padding: 0.28rem 0.32rem 0.34rem;
  color: var(--color-ink-muted);
  border-bottom: 2px solid transparent;
  transition:
    color 0.15s ease,
    border-color 0.15s ease;
}
.folio-rail-step:hover {
  color: var(--color-ink);
}
.folio-rail-step[data-filled="true"] {
  color: var(--color-ink-light);
  border-bottom-color: color-mix(
    in srgb,
    var(--color-ink-muted) 45%,
    transparent
  );
}
.folio-rail-step[aria-current="step"] {
  color: var(--color-vermilion);
  border-bottom-color: var(--color-vermilion);
}

/* Column frames scroll inside the folio, never the page. The gutter is
   a filing-cabinet crease rather than a scrollbar trough. */
.folio-column {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--color-paper-3) transparent;
}
.folio-column::-webkit-scrollbar {
  width: 6px;
}
.folio-column::-webkit-scrollbar-thumb {
  background: var(--color-paper-3);
  border-radius: 3px;
}
.folio-column::-webkit-scrollbar-track {
  background: transparent;
}

@media (prefers-reduced-motion: reduce) {
  .folio-shift {
    animation: none;
  }
  .dossier-folio-frame,
  .dossier-folio-frame[data-filing-state="filed"],
  .dossier-filed-confirmation,
  .dossier-filed-confirmation__paper,
  .filed-dossier-paper {
    animation: none;
    transition: none;
  }
  .type-caret {
    animation: none;
  }
  .carriage-input {
    transition: none;
  }
}

