export interface NumericBounds {
  min?: number;
  max?: number;
  step?: number;
  emptyValue?: number;
}

interface NumericStepperProps extends NumericBounds {
  value: number | "" | null | undefined;
  ariaLabel: string;
  placeholder?: string;
  suffix?: string;
  disabled?: boolean;
  density?: "regular" | "compact";
  class?: string;
  title?: string;
