      {items.length > 0 ? (
        renderBranch(items, props, navigate$)
      ) : (
        <p
          class="m-0 px-2 py-3 text-sm leading-5 text-[var(--color-ink-muted)]"
          role="status"
        >
          {props.emptyLabel || "Add a heading to build the outline."}
        </p>
      )}
    </nav>
  );
});
import {
  $,
  component$,
  sync$,
  useSignal,
  type PropFunction,
} from "@builder.io/qwik";

export const TABLE_GRID_DEFAULT_ROWS = 8;
export const TABLE_GRID_DEFAULT_COLUMNS = 10;
export const TABLE_INSERT_MAX_ROWS = 20;
export const TABLE_INSERT_MAX_COLUMNS = 12;

export interface TableDimensions {
  rows: number;
  columns: number;
}

export type TableGridDirection =
  | "ArrowUp"
  | "ArrowDown"
  | "ArrowLeft"
  | "ArrowRight"
  | "Home"
  | "End";

function positiveInteger(value: unknown, fallback: number): number {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Math.max(1, Math.floor(numeric)) : fallback;
}

export function clampTableDimensions(
  dimensions: Partial<TableDimensions>,
  limits: Partial<TableDimensions> = {},
): TableDimensions {
  const maxRows = Math.min(
    TABLE_INSERT_MAX_ROWS,
    positiveInteger(limits.rows, TABLE_INSERT_MAX_ROWS),
  );
  const maxColumns = Math.min(
    TABLE_INSERT_MAX_COLUMNS,
    positiveInteger(limits.columns, TABLE_INSERT_MAX_COLUMNS),
  );
  return {
    rows: Math.min(maxRows, positiveInteger(dimensions.rows, 1)),
    columns: Math.min(maxColumns, positiveInteger(dimensions.columns, 1)),
  };
}

export function moveTableGridSelection(
  current: TableDimensions,
  direction: TableGridDirection,
  limits: TableDimensions,
): TableDimensions {
  const selection = clampTableDimensions(current, limits);
  switch (direction) {
    case "ArrowUp":
      return { ...selection, rows: Math.max(1, selection.rows - 1) };
    case "ArrowDown":
      return {
        ...selection,
        rows: Math.min(limits.rows, selection.rows + 1),
      };
    case "ArrowLeft":
      return {
        ...selection,
        columns: Math.max(1, selection.columns - 1),
      };
    case "ArrowRight":
      return {
        ...selection,
        columns: Math.min(limits.columns, selection.columns + 1),
      };
    case "Home":
      return { rows: 1, columns: 1 };
    case "End":
      return clampTableDimensions(limits, limits);
  }
}

export function isTableGridCellSelected(
  cell: TableDimensions,
  selection: TableDimensions,
): boolean {
  return cell.rows <= selection.rows && cell.columns <= selection.columns;
}

interface TableInsertionGridProps {
  maxRows?: number;
  maxColumns?: number;
  withHeaderRow?: boolean;
  onInsert$: PropFunction<
    (rows: number, columns: number, withHeaderRow: boolean) => void
  >;
  onCancel$?: PropFunction<() => void>;
}

/**
 * Keyboard and pointer accessible N-by-M table chooser.
 *
 * The highlighted rectangle is the insertion size. Arrow keys resize it,
 * Enter inserts, and Escape returns control to the caller.
 */
export const TableInsertionGrid = component$<TableInsertionGridProps>(
  (props) => {
    const limits = clampTableDimensions(
      {
        rows: props.maxRows ?? TABLE_GRID_DEFAULT_ROWS,
        columns: props.maxColumns ?? TABLE_GRID_DEFAULT_COLUMNS,
      },
      {
        rows: TABLE_INSERT_MAX_ROWS,
        columns: TABLE_INSERT_MAX_COLUMNS,
      },
    );
    const selectedRows = useSignal(1);
    const selectedColumns = useSignal(1);

    const select = $((rows: number, columns: number) => {
      const next = clampTableDimensions({ rows, columns }, limits);
      selectedRows.value = next.rows;
      selectedColumns.value = next.columns;
    });

    const commit = $((rows?: number, columns?: number) => {
      const dimensions = clampTableDimensions(
        {
          rows: rows ?? selectedRows.value,
          columns: columns ?? selectedColumns.value,
        },
        limits,
      );
      return props.onInsert$(
        dimensions.rows,
        dimensions.columns,
        props.withHeaderRow ?? true,
      );
    });

    const preventGridKeys = sync$((event: KeyboardEvent) => {
      if (
        [
          "ArrowUp",
          "ArrowDown",
          "ArrowLeft",
          "ArrowRight",
          "Home",
          "End",
          "Enter",
          "Escape",
        ].includes(event.key)
      ) {
        event.preventDefault();
      }
    });

    const handleGridKey = $((event: KeyboardEvent) => {
      if (event.key === "Enter") {
        void commit();
        return;
      }
      if (event.key === "Escape") {
        void props.onCancel$?.();
        return;
      }
      if (
        ![
          "ArrowUp",
          "ArrowDown",
          "ArrowLeft",
          "ArrowRight",
          "Home",
          "End",
        ].includes(event.key)
      ) {
        return;
      }
      const next = moveTableGridSelection(
        { rows: selectedRows.value, columns: selectedColumns.value },
        event.key as TableGridDirection,
        limits,
      );
      selectedRows.value = next.rows;
      selectedColumns.value = next.columns;
    });

    const rows = Array.from({ length: limits.rows }, (_, index) => index + 1);
    const columns = Array.from(
      { length: limits.columns },
      (_, index) => index + 1,
    );
    const selection = {
      rows: selectedRows.value,
      columns: selectedColumns.value,
    };

    return (
      <div
        data-table-insertion-grid
        class="w-fit bg-[var(--color-paper)] p-3 text-[var(--color-ink)]"
        style={{
          border: "1px solid var(--color-paper-3)",
          borderRadius: "4px",
          fontFamily: "var(--font-typewriter)",
          boxShadow:
            "0 6px 8px color-mix(in srgb, var(--color-ink) 12%, transparent)",
        }}
      >
        <p
          class="mb-2 text-[0.72rem] font-semibold"
          aria-live="polite"
          aria-atomic="true"
        >
          {selection.rows} × {selection.columns} table
        </p>
        <div
          role="grid"
          aria-label="Choose table size"
          aria-rowcount={limits.rows}
          aria-colcount={limits.columns}
          tabIndex={0}
          class="grid gap-1 outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-vermilion)]"
          style={{
            gridTemplateColumns: `repeat(${limits.columns}, 1.15rem)`,
          }}
          onKeyDown$={[preventGridKeys, handleGridKey]}
        >
          {rows.flatMap((row) =>
            columns.map((column) => {
              const active = isTableGridCellSelected(
                { rows: row, columns: column },
                selection,
              );
              return (
                <button
                  key={`${row}:${column}`}
                  type="button"
                  role="gridcell"
                  aria-rowindex={row}
                  aria-colindex={column}
                  aria-selected={active}
                  aria-label={`${row} by ${column} table`}
                  class={[
                    "h-[1.15rem] w-[1.15rem] border transition-colors duration-150",
                    active
                      ? "border-[var(--color-vermilion)] bg-[color-mix(in_srgb,var(--color-vermilion)_22%,transparent)]"
                      : "border-[var(--color-paper-3)] bg-[var(--color-paper-2)] hover:border-[var(--color-ink-muted)]",
                  ]}
                  onPointerEnter$={() => select(row, column)}
                  onFocus$={() => select(row, column)}
                  onClick$={() => commit(row, column)}
                />
              );
            }),
          )}
        </div>
        <p class="mt-2 text-[0.62rem] text-[var(--color-ink-muted)]">
          Arrow keys resize. Enter inserts.
        </p>
      </div>
    );
  },
);
import { component$, type PropFunction } from "@builder.io/qwik";
import type { LayoutSettings } from "../../types";
import { PageFurnitureEditor } from "./page-furniture-editor";

export interface PageChromeProps {
  /** Number of sheets the engine says the manuscript occupies. */
  pageCount: number;
  /** Sheet height in CSS px. */
  pageH: number;
  /** Gap painted between two sheets, CSS px. */
  gap: number;
  /** Top page margin, CSS px — where the running header sits. */
  marginTop: number;
  /** Bottom page margin, CSS px — where the page number sits. */
  marginBottom: number;
  /** Left page margin, CSS px. */
  marginLeft: number;
  /** Right page margin, CSS px. */
  marginRight: number;
  layout: LayoutSettings;
  /** Shown in the running header, alongside the author. */
  title?: string;
  author?: string;
  headerText?: string;
  footerText?: string;
  onHeaderCommit$?: PropFunction<(value: string) => void>;
  onFooterCommit$?: PropFunction<(value: string) => void>;
  /** False when the engine fell back to a continuous column. */
  active: boolean;
  /** Faded out in zen mode, like the toolbar and the ruler. */
  zen?: boolean;
}

/**
 * The visible page furniture: sheet edges, running headers, page numbers.
 *
 * None of this is in the document. The pagination engine guarantees that page
 * *k*'s content top sits at exactly `k * (pageH + gap)`, which means every
 * position here is a multiply rather than a measurement — this component never
 * reads the DOM and never needs to know where a break actually landed.
 *
 * It renders *behind* the prose (`z-index: 0` against the editor's own stacking
 * context) and is inert to the pointer, so clicking a page number puts the
 * caret in the text underneath rather than stealing focus from the manuscript.
 *
 * The page numbers are real text nodes rather than CSS counters. That is
 * deliberate: `counter(page)` is only readable inside a `@page` margin box,
 * which Chrome does not implement, so a counter-based footer would print
 * blank. Taking the integer from the engine is what lets screen and paper
 * agree on what page seven is.
 */
export const PageChrome = component$<PageChromeProps>((props) => {
  if (!props.active || props.pageCount < 1) return null;

  const period = props.pageH + props.gap;
  const pages = Array.from({ length: props.pageCount }, (_, i) => i);
  const showHeader = props.layout.runningHeader === true;
  const showNumbers = props.layout.pageNumbers !== false;

  return (
    <div
      class={`twyne-page-chrome ${props.zen ? "zen" : ""}`}
      aria-label="Page headers and footers"
      style={{
        // Absolutely positioned against the page canvas's padding box, whose
        // top edge is page 0's sheet top and whose width is the full sheet.
        position: "absolute",
        left: "0",
        right: "0",
        top: "0",
        height: `${Math.max(0, props.pageCount * period - props.gap)}px`,
        pointerEvents: "none",
        zIndex: "0",
      }}
    >
      {pages.map((k) => (
        <div
          key={k}
          class="twyne-page-sheet"
          data-page={k + 1}
          style={{
            position: "absolute",
            left: "0",
            right: "0",
            top: `${k * period}px`,
            height: `${props.pageH}px`,
          }}
        >
          {showHeader && (
            <div
              class="twyne-page-running-header"
              style={{
                position: "absolute",
                left: `${props.marginLeft}px`,
                right: `${props.marginRight}px`,
                // Sit the header inside the top margin, clear of the text.
                top: `${Math.max(4, props.marginTop * 0.45)}px`,
              }}
            >
              <span class="twyne-page-header-title">
                <PageFurnitureEditor
                  kind="header"
                  value={props.headerText}
                  fallback={props.title || "Untitled"}
                  placeholder="Running header"
                  label={`Edit running header on page ${k + 1}`}
                  emitFolioEvent={false}
                  onCommit$={(change) => props.onHeaderCommit$?.(change.value)}
                />
              </span>
              {props.author && (
                <span class="twyne-page-header-author">{props.author}</span>
              )}
            </div>
          )}
          {(showNumbers || props.footerText) && (
            <div
              class="twyne-page-running-footer"
              style={{
                position: "absolute",
                left: `${props.marginLeft}px`,
                right: `${props.marginRight}px`,
                bottom: `${Math.max(4, props.marginBottom * 0.4)}px`,
              }}
            >
              <span class="twyne-page-footer-text">
                <PageFurnitureEditor
                  kind="footer"
                  value={props.footerText}
