      id: "probe-3",
      kind: "choice",
      prompt: "Which city should provide the closing example?",
      options: ["Toronto", "Halifax", "Winnipeg"],
      relatesTo: "successSignal",
    },
  ],
  updatedAt: Date.UTC(2026, 7, 31, 14, 45),
};

