 53	interface HeadlineRun {
 54	  text: string;
 55	  struck: boolean;
 56	}
 57	interface HeadlineFrame {
 58	  runs: HeadlineRun[];
 59	  hold: number;
 60	  leaving: boolean;
 61	  headline: number;
 62	}
 63	
 64	const TYPE_MS = 46; // one keystroke
 65	const SETTLE_MS = 700; // the beat before the editor's mark lands
 66	const STRIKE_MS = 900; // the rule drawn through the struck words
 67	const READ_MS = 2600; // the finished line, held to be read
 68	const LEAVE_MS = 620; // the line pulled up out of the carriage
 69	
 70	/**
 71	 * Every state of the headline, precomputed. Playing it back is then just
 72	 * "advance an index on a timer", which keeps the component free of nested
 73	 * timeouts and makes the whole sequence deterministic.
 74	 */
 75	const { frames: HEADLINE_FRAMES, initial: INITIAL_FRAME } = (() => {
 76	  const frames: HeadlineFrame[] = [];
 77	  let initial = 0;
 78	
 79	  HEADLINES.forEach((headline, index) => {
 80	    const push = (runs: HeadlineRun[], hold: number, leaving = false) =>
 81	      frames.push({
 82	        runs: runs.filter((run) => run.text.length > 0),
 83	        hold,
