 99	      push([lead, { text: strike, struck: true }], STRIKE_MS);
100	      for (let i = 1; i <= replacement.length; i++) {
101	        push(
102	          [
103	            lead,
104	            { text: strike, struck: true },
105	            { text: replacement.slice(0, i), struck: false },
106	          ],
107	          TYPE_MS,
108	        );
109	      }
110	      push(
111	        [
112	          lead,
113	          { text: strike, struck: true },
