 24	/**
 25	 * The hero headline types itself out, then a copy-editor strikes a word and
 26	 * writes the correction after it — the gesture the whole product is about.
 27	 *
 28	 * `lead` types first. If a `strike` is given it types too, sits for a beat,
 29	 * takes the rule through it, and then `replacement` is typed after the
 30	 * correction. Headline 0 carries no correction on purpose: it is what the
 31	 * server renders and what crawlers and screen readers get, so it has to read
 32	 * as a clean sentence.
 33	 */
 34	const HEADLINES = [
 35	  {
 36	    lead: "Draft with a room full of editors.",
 37	    deck: "Twyne is a writing app for essays and long-form drafts. Five editorial personas, a grading rubric, and a citation desk read every draft against your brief.",
 38	  },
 39	  {
