 49	    deck: "A Target Fit judge scores relevance on its own, and caps every craft metric whenever a draft drifts off its subject.",
 50	  },
 51	];
 52	
 53	interface HeadlineRun {
 54	  text: string;
 55	  struck: boolean;
 56	}
 57	interface HeadlineFrame {
 58	  runs: HeadlineRun[];
 59	  hold: number;
 60	  leaving: boolean;
 61	  headline: number;
 62	}
 63	
 64	const TYPE_MS = 46; // one keystroke
 65	const SETTLE_MS = 700; // the beat before the editor's mark lands
 66	const STRIKE_MS = 900; // the rule drawn through the struck words
 67	const READ_MS = 2600; // the finished line, held to be read
 68	const LEAVE_MS = 620; // the line pulled up out of the carriage
 69	
 70	/**
 71	 * Every state of the headline, precomputed. Playing it back is then just
 72	 * "advance an index on a timer", which keeps the component free of nested
 73	 * timeouts and makes the whole sequence deterministic.
 74	 */
 75	const { frames: HEADLINE_FRAMES, initial: INITIAL_FRAME } = (() => {
 76	  const frames: HeadlineFrame[] = [];
 77	  let initial = 0;
 78	
 79	  HEADLINES.forEach((headline, index) => {
 80	    const push = (runs: HeadlineRun[], hold: number, leaving = false) =>
 81	      frames.push({
 82	        runs: runs.filter((run) => run.text.length > 0),
 83	        hold,
 84	        leaving,
 85	        headline: index,
 86	      });
 87	
 88	    for (let i = 1; i <= headline.lead.length; i++) {
 89	      push([{ text: headline.lead.slice(0, i), struck: false }], TYPE_MS);
 90	    }
 91	
 92	    const lead = { text: headline.lead, struck: false };
 93	    if (headline.strike && headline.replacement) {
 94	      const { strike, replacement } = headline;
 95	      for (let i = 1; i <= strike.length; i++) {
 96	        push([lead, { text: strike.slice(0, i), struck: false }], TYPE_MS);
 97	      }
 98	      push([lead, { text: strike, struck: false }], SETTLE_MS);
 99	      push([lead, { text: strike, struck: true }], STRIKE_MS);
100	      for (let i = 1; i <= replacement.length; i++) {
101	        push(
102	          [
103	            lead,
104	            { text: strike, struck: true },
105	            { text: replacement.slice(0, i), struck: false },
106	          ],
107	          TYPE_MS,
108	        );
109	      }
110	      push(
111	        [
112	          lead,
113	          { text: strike, struck: true },
114	          { text: replacement, struck: false },
115	        ],
116	        READ_MS,
117	      );
118	    } else {
119	      push([lead], READ_MS);
120	    }
121	
122	    // The completed first headline is what the server renders, and where the
123	    // loop starts — so the first paint never flickers or retypes itself.
124	    if (index === 0) initial = frames.length - 1;
