  57	
  58	  /* ── Type stack ──────────────────────────────────────── */
  59	  --font-display: "Libre Baskerville", "Playfair Display", Georgia, serif;
  60	  --font-serif: "Lora", "Crimson Pro", Georgia, "Times New Roman", serif;
  61	  --font-sans: "DM Sans", "Inter", system-ui, sans-serif;
  62	  --font-mono: "JetBrains Mono", "Fira Code", monospace;
  63	  --font-typewriter: "Special Elite", "Courier New", monospace;
  64	}
  65	
  66	/* ── Semantic z-scale ────────────────────────────────────── */
  67	:root {
  68	  --z-dropdown: 30;
  69	  --z-sticky: 20;
  70	  --z-overlay: 40;
  71	  --z-modal: 50;
