2709	}
2710	/* The page's primary CTA is ink-on-paper, which vanishes against the desk —
2711	   so on the hero it answers in vermilion, and the secondary is outlined in
2712	   the hero's own cream. */
2713	.landing-hero .broadsheet-cta {
