2782	  animation: landing-strike 0.42s cubic-bezier(0.22, 1, 0.36, 1) forwards;
2783	}
2784	@keyframes landing-strike {
2785	  to {
2786	    transform: scaleX(1);
2787	  }
2788	}
2789	
2790	.landing-title .landing-rotator__caret {
2791	  display: inline-block;
2792	  width: 0.07em;
2793	  height: 0.78em;
2794	  margin-left: 0.07em;
