2908	  border-radius: 2px;
2909	  box-shadow:
2910	    0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
2911	    0 26px 44px -32px color-mix(in srgb, var(--shade) 52%, transparent),
2912	    0 3px 9px -6px color-mix(in srgb, var(--shade) 40%, transparent);
