2605	/* ─────────────────────────────────────────────────────────────
2606	 * Landing photo essay — the plates
2607	 *   .landing-hero     : full-bleed photograph the hero type is set on
2608	 *   .landing-plate    : one alternating image/text spread
2609	 *   [data-reveal]     : scroll-triggered fade + rise
2610	 *
2611	 * The reveal's hidden start state is scoped to [data-reveal-ready],
2612	 * which JS sets. Without JS nothing is ever hidden, so the SSR'd
2613	 * page reads exactly as it did before — and stays crawlable.
2614	 * ───────────────────────────────────────────────────────────── */
2615	
2616	/* ── Hero: the type is set on the desk ──
2617	 * Full-bleed out of .landing-shell's centred column. .landing-page already
2618	 * sets `overflow: clip`, so 100vw can't raise a scrollbar.
2619	 *
2620	 * The hero is a fixed dark plate in every theme — its ink is hard-coded
2621	 * cream rather than themed, because the ground underneath is a dark
2622	 * photograph in foolscap, broadsheet and nightpress alike. Only the feather
2623	 * at top and bottom is theme-aware, so the plate dissolves into whatever
2624	 * colour the page happens to be.
2625	 */
2626	.landing-hero {
2627	  --hero-ink: #f7f0dd;
2628	  --hero-ink-soft: #dbcfb6;
2629	  /* The page vermilion goes muddy on near-black, so the hero's editor's
2630	     marks — the strike rule and the caret — use a brighter one. */
2631	  --mark: #f2564e;
2632	  --mark-dim: #a99b83;
2633	  position: relative;
2634	  isolation: isolate;
2635	  width: 100vw;
2636	  margin-inline: calc(50% - 50vw);
2637	  overflow: hidden;
2638	  display: grid;
2639	  place-items: center;
2640	  min-height: min(84vh, 720px);
2641	  padding: 5rem 1.25rem;
2642	  background: #17130f;
2643	}
2644	.landing-hero__photo {
2645	  position: absolute;
2646	  inset: 0;
2647	  z-index: -2;
2648	  width: 100%;
2649	  height: 100%;
2650	  object-fit: cover;
2651	  transform-origin: 50% 50%;
2652	  animation: landing-hero-drift 26s ease-in-out infinite alternate;
2653	}
2654	/* Slow ken-burns. Off-screen animations are throttled by the browser, so
2655	   this costs nothing once the hero has scrolled away. */
2656	@keyframes landing-hero-drift {
2657	  from {
2658	    transform: scale(1);
2659	  }
2660	  to {
2661	    transform: scale(1.07);
2662	  }
2663	}
2664	/* Scrim. The radial darkens the middle so the headline always has ground to
2665	   sit on whatever the photograph is doing; the linear feathers the plate
2666	   into the page above and below. */
2667	.landing-hero::before {
2668	  content: "";
2669	  position: absolute;
2670	  inset: 0;
2671	  z-index: -1;
2672	  background:
2673	    linear-gradient(
2674	      180deg,
2675	      var(--color-paper) 0%,
2676	      color-mix(in srgb, var(--color-paper) 52%, transparent) 7%,
2677	      transparent 17%,
2678	      transparent 85%,
2679	      color-mix(in srgb, var(--color-paper) 52%, transparent) 95%,
2680	      var(--color-paper) 100%
2681	    ),
2682	    radial-gradient(
2683	      ellipse 72% 66% at 50% 50%,
2684	      rgba(12, 10, 8, 0.84) 0%,
2685	      rgba(12, 10, 8, 0.6) 52%,
2686	      rgba(12, 10, 8, 0.3) 100%
2687	    );
2688	}
2689	.landing-hero__inner {
2690	  position: relative;
2691	  z-index: 1;
2692	  /* The hero centres its child with `place-items`, which also makes the grid
2693	     item size to its content — so the block was 729px wide against the
