                  <p class="note">{a.note}</p>
                </div>
              ))}
            </div>
            <ul class="mx-auto mt-6 max-w-xl space-y-3 px-2 lg:hidden">
              {annotations.map((a) => (
                <li key={a.id} class="flex items-baseline gap-3">
